import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import manifest from '@/app/manifest';

/**
 * App icons (favicon, apple-touch, manifest) are generated by scripts/build-app-icons.mjs.
 * Guards against the create-next-app / Vercel defaults coming back and against a manifest
 * that points at icons that were never generated.
 */

const root = path.resolve(__dirname, '..');
const read = (rel: string) => fs.readFileSync(path.join(root, rel));

/** Width and height from a PNG IHDR chunk. */
function pngSize(buf: Buffer): [number, number] {
  expect(buf.subarray(1, 4).toString('ascii')).toBe('PNG');
  return [buf.readUInt32BE(16), buf.readUInt32BE(20)];
}

describe('app icons', () => {
  it('manifest icons exist with the declared sizes, including a maskable one', () => {
    const m = manifest();
    expect(m.short_name).toBe('Blanmont');
    expect(m.icons?.some((i) => i.purpose === 'maskable')).toBe(true);
    for (const icon of m.icons ?? []) {
      const [w, h] = pngSize(read(path.join('public', icon.src)));
      expect(`${w}x${h}`).toBe(icon.sizes);
    }
  });

  it('apple-touch icon is 180px and opaque (iOS fills alpha with black)', () => {
    const buf = read('app/apple-icon.png');
    expect(pngSize(buf)).toEqual([180, 180]);
    // IHDR colour type 2 = truecolour without alpha.
    expect(buf.readUInt8(25)).toBe(2);
  });

  it('favicon.ico is the generated Heart Line, not the Next.js default', () => {
    const ico = read('app/favicon.ico');
    expect(ico.readUInt16LE(2)).toBe(1); // icon type
    const sizes = Array.from({ length: ico.readUInt16LE(4) }, (_, n) => ico.readUInt8(6 + n * 16));
    expect(sizes).toEqual([16, 32, 48]);
  });

  it('vector favicon draws in route red brand-vif', () => {
    expect(read('app/icon.svg').toString()).toContain('stroke="#e03e3e"');
  });

  it('create-next-app stock SVGs are gone', () => {
    for (const f of ['vercel.svg', 'next.svg', 'globe.svg', 'window.svg', 'file.svg'])
      expect(fs.existsSync(path.join(root, 'public', f))).toBe(false);
  });
});
